using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class ArcadeTests {
 static int checks,failures;static void Check(bool ok,string label){checks++;if(!ok){failures++;Console.WriteLine("FAIL Arcade: "+label);}}
 static void Call(Simulation s,string name,params object[] args){typeof(Simulation).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance,null,Array.ConvertAll(args,a=>a.GetType()),null).Invoke(s,args);}
 static void Field(Simulation s,string name,float value){typeof(Simulation).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(s,value);}
 public static Simulation Duel(int seed,float jumpTime,bool rosterId){Simulation s=new Simulation(seed);s.Players.Clear();Player runner=new Player(0,25,0,"RB",22,8);runner.OVR=85;runner.HasBall=true;runner.ClubId=rosterId?7:-1;Player defender=new Player(0,25.65f,1,"CB",24,7);defender.OVR=80;s.Players.Add(runner);s.Players.Add(defender);s.Controlled=runner;s.State=Phase.Live;s.Jump();Field(s,"skillTime",jumpTime);runner.PoseTime=jumpTime;return s;}
 static Simulation OpenRun(bool practice){Simulation s=new Simulation(42);s.Practice=practice;s.Players.Clear();Player runner=new Player(0,40,0,"RB",22,8);runner.HasBall=true;s.Players.Add(runner);s.Players.Add(new Player(0,5,1,"CB",24,6));s.Controlled=runner;s.State=Phase.Live;s.Sprint=true;return s;}
 public static int Run(){checks=failures=0;int good=0,early=0,late=0,goodRisk=0,badRisk=0;for(int seed=0;seed<160;seed++){Simulation s=Duel(5000+seed,.32f,true);s.Update(1f/60,0,1);if(s.HurdlesMade>0)good++;if(s.Fumbles>0||s.InjuryReports.Count>0)goodRisk++;s=Duel(5000+seed,.56f,true);s.Update(1f/60,0,1);if(s.HurdlesMade>0)early++;if(s.Fumbles>0||s.InjuryReports.Count>0)badRisk++;s=Duel(6000+seed,.05f,false);s.Update(1f/60,0,1);if(s.HurdlesMade>0)late++;}Console.WriteLine("Hurdle timing: "+good+"/160 well timed; "+early+" early, "+late+" late; penalties good="+goodRisk+", mistimed="+badRisk);Check(good>90&&good<155,"timed hurdles sometimes clear DBs");Check(early==0&&late==0,"early and late hops cannot clear a standing defender");Check(badRisk>goodRisk*1.5&&badRisk>45,"mistimed landings carry meaningful fumble/injury risk");
  Simulation normal=OpenRun(true),fast=OpenRun(false);for(int i=0;i<180;i++){normal.Update(1f/60,0,1);fast.Update(1f/60,0,1);}Check(fast.Controlled.Z>normal.Controlled.Z+6&&fast.OpenFieldPace>1.4f,"clear breakaways finish sooner");Check(Math.Abs(fast.Clock-57)<.03f,"breakaway pace preserves real clock rate");fast.Update(.016f,1,0);Check(fast.OpenFieldPace==1,"turning restores normal pace immediately");fast=OpenRun(false);fast.Players[1].Z=fast.Controlled.Z+8;for(int i=0;i<30;i++)fast.Update(1f/60,0,1);Check(fast.OpenFieldPace==1,"defenders ahead prevent breakaway acceleration");
  Simulation clock=new Simulation(1);clock.Clock=30;Call(clock,"EndPlay",25f,"TACKLED",false);Check(clock.Clock==26&&clock.LastRunoff==4,"inbounds tackle takes four seconds");Call(clock,"ApplyRunoff");Check(clock.Clock==26,"same play cannot charge runoff twice");clock=new Simulation(1);clock.Clock=30;Call(clock,"EndPlay",25f,"OUT: +5 YDS",false);Check(clock.Clock==30&&clock.LastRunoff==0,"out of bounds stops clock");clock=new Simulation(1);clock.Clock=30;Call(clock,"EndPlay",20f,"INCOMPLETE PASS",true);Check(clock.Clock==30,"incompletion has no runoff");clock=new Simulation(1);clock.Quarter=2;clock.Clock=3;Call(clock,"EndPlay",25f,"TACKLED",false);Check(clock.State==Phase.Halftime&&clock.Quarter==3,"runoff ending half reaches halftime");
  clock=new Simulation(1);clock.Snap();clock.BeginPass(0);Check(clock.ThrowAway()&&!clock.Charging&&clock.State==Phase.Flight,"RS click cancels charge and launches throwaway");Check(Math.Abs(clock.FlightTargetX)>FieldGeometry.HalfWidth&&clock.Attempts==1,"throwaway is a real sideline pass attempt");for(int i=0;i<45;i++)clock.Update(.02f,0,0);Check(clock.State==Phase.Dead&&clock.Down==2&&clock.LastRunoff==0&&clock.Interceptions==0,"throwaway ends incomplete without runoff or interception");clock.Next();clock.Snap();clock.Controlled.Z=clock.Spot+1;Check(!clock.ThrowAway(),"no throwaway after line of scrimmage");clock=new Simulation(1);clock.ThrowAway();Check(clock.State==Phase.PreSnap&&clock.Attempts==0,"throwaway unavailable before snap");
  clock=new Simulation(1);clock.Clock=30;Call(clock,"ScoreTouchdown");Check(clock.Clock==26,"touchdown has one runoff");clock.ChooseConversion(false);clock.KickMeter=.5f;clock.StopKick();for(int i=0;i<44;i++)clock.Update(.05f,0,0);Check(clock.Clock==26,"untimed PAT has no extra runoff");clock=new Simulation(1);clock.Clock=3;clock.Punt();Check(clock.Quarter==2&&clock.State==Phase.Opponent,"quarter-ending punt preserves opponent possession");
  string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-arcade-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
   Franchise club=Franchise.Create(new Profile(),new Roster());Simulation s=new Simulation(12);club.Apply(s,1);s.NewGame();Player patient=s.Players[1];int id=patient.ClubId;s.Controlled.HasBall=false;s.Controlled=patient;patient.HasBall=true;patient.Z=31;s.State=Phase.Live;Call(s,"Injure",patient,true);int weeks=s.InjuryReports[0].Weeks;Check(weeks>=3&&weeks<=6&&!patient.Active,"hard landing removes player for several weeks");Call(s,"EndPlay",31f,"TACKLED",false);Check(s.AmbulanceActive,"injury launches pickup after whistle");float start=s.AmbulanceX,freeze=s.Clock;for(int i=0;i<38;i++)s.Update(.05f,0,0);Check(s.AmbulanceX>start+15&&patient.KnockTime>0&&s.Clock==freeze,"ambulance reaches prone patient while clock is stopped");for(int i=0;i<12;i++)s.Update(.05f,0,0);Check(s.AmbulanceLoaded&&!patient.Active,"patient is loaded and cannot rejoin play");s.SkipAmbulance();Check(!s.AmbulanceActive,"pickup is skippable");s.Next();Check(s.Players[1].ClubId!=id,"healthy reserve replaces injured starter next snap");Fixture fixture=club.UserGame;club.FinishGame(fixture.Id,21,7,s.MatchInjuries,s.Box,s.InjuryReports);Check(club.Players.Find(p=>p.Id==id).InjuryWeeks==weeks,"exact recovery survives match result and weekly advance");Check(club.News.Exists(news=>news.Contains("injured / "+weeks+" weeks recovery")),"club news uses the actual injury duration");Franchise saved=Franchise.Load(new Profile(),new Roster());Check(saved.Players.Find(p=>p.Id==id).InjuryWeeks==weeks&&saved.Players.Find(p=>p.Id==id).InjuryType=="HARD LANDING","injury severity and recovery save/load");
   StadiumMixer mix=new StadiumMixer();mix.SetGain(2,0);mix.Play("whistle");short[] sound=new short[FootballSounds.Rate*2];mix.Render(sound,FootballSounds.Rate);long energy=0;foreach(short sample in sound)energy+=Math.Abs((int)sample);Check(energy==0,"whistle channel can be silent independently");mix.Play("hit");mix.Render(sound,FootballSounds.Rate);energy=0;foreach(short sample in sound)energy+=Math.Abs((int)sample);Check(energy>0,"muting whistles preserves hits");mix.SetGain(1,0);mix.Stadium=true;mix.Render(sound,FootballSounds.Rate);energy=0;foreach(short sample in sound)energy+=Math.Abs((int)sample);Check(energy==0,"crowd channel can be muted independently");
   using(GameAudio audio=new GameAudio()){audio.Mix.SetGain(2,.1f);audio.Mix.SetGain(1,.4f);audio.Muted=true;audio.SaveSettings();}using(GameAudio audio=new GameAudio()){Check(audio.Muted&&Math.Abs(audio.Mix.GetGain(2)-.1f)<.001&&Math.Abs(audio.Mix.GetGain(1)-.4f)<.001,"mixer and mute preferences persist");}
  }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}
  Console.WriteLine("Arcade: "+checks+" checks, "+failures+" failures");return failures;
 }
}
}
